def transform(grid):
    height, width = len(grid), len(grid[0])
    pattern = [[0 if value else 1 for value in row] for row in grid]
    out = [[0] * (width * 3) for _ in range(height * 3)]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                for i in range(3):
                    for j in range(3):
                        if pattern[i][j]:
                            out[3 * r + i][3 * c + j] = value
    return out
